def place(region):
    cands = [s for s in shards if s.region == region and s.accepting]
    def load(s):
        return 0.5*s.bytes/s.max_bytes + 0.3*s.qps/s.max_qps + 0.2*s.tenants/s.max_tenants
    cands = [s for s in cands if load(s) < 0.7]
    if not cands:
        return provision_new_shard(region)
    return min(cands, key=load)

